import re, subprocess

def git(*args):
    return subprocess.run(["git", *args], check=True, stdout=subprocess.PIPE).stdout.decode("utf-8", "surrogateescape")

def show(rev):
    return git("show", rev + ":deps.lock").splitlines(keepends=True)

def block(lines):
    start = None
    for i, line in enumerate(lines):
        s = line.lstrip()
        if s.startswith("packages") and "[" in s:
            start = i
            break
    if start is None:
        return None
    depth = 0
    end = None
    for j in range(start, len(lines)):
        depth += lines[j].count("[") - lines[j].count("]")
        if j > start and depth <= 0:
            end = j
            break
    if end is None:
        return None
    return start, end

def package_names(lines):
    b = block(lines)
    if b is None:
        return None
    start, end = b
    names = set()
    for line in lines[start + 1:end]:
        s = line.strip()
        if not s or s.startswith("#"):
            continue
        m = re.search(r'"([^"]+)"', s)
        if m is None:
            m = re.search(r"'([^']+)'", s)
        if m:
            names.add(m.group(1).split()[0])
        else:
            token = s.split()[0].rstrip(",")
            if token:
                names.add(token)
    return names

def version(lines):
    for line in lines:
        m = re.match(r'^\s*version\s*=\s*(\S+)', line)
        if m:
            return m.group(1)
    return None

final = show("HEAD")
local = show("HEAD^1")
upstream = show("HEAD^2")
base_rev = git("merge-base", "HEAD^1", "HEAD^2").strip()
base = show(base_rev)

if any(line.startswith(("<<<<<<<", "=======", ">>>>>>>")) for line in final):
    raise SystemExit("conflict markers remain")

fn = package_names(final)
ln = package_names(local)
un = package_names(upstream)
bn = package_names(base)
if fn is None or ln is None or un is None or bn is None:
    raise SystemExit("missing package block")

local_removals = bn - ln
local_additions = ln - bn
upstream_additions = un - bn
if not local_removals.isdisjoint(fn):
    raise SystemExit("a locally removed package was re-added")
if not local_additions <= fn:
    raise SystemExit("a local package addition was lost")
if not upstream_additions <= fn:
    raise SystemExit("an upstream package addition is missing")
if fn != (ln | upstream_additions):
    raise SystemExit("unexpected package entries")

bv = version(base)
lv = version(local)
fv = version(final)
uv = version(upstream)
expected_version = uv if uv != bv else lv
if expected_version is not None and fv != expected_version:
    raise SystemExit("version metadata is not the expected merge")
